/**
 * @param {string} s
 * @return {number}
 */
var countBinarySubstrings = function(s) {
    let count = 0;
    let prev = 0;
    let cur = '0';
    let res = 0;

    for (let i = 0; i < s.length; i++) {
        if (s[i] === cur) {
            count++;
        } else {
            cur = s[i];
            prev = count;
            count = 1;
        }

        if (count <= prev) {
            res++;
        }
    }

    return res;
};
